Code
lifState = {
  lifReset;
  const dt = 0.1, win = 300, R = 2, Vrest = -65, Vreset = -70, refr = 2;
  const n = Math.round(win / dt);
  const V = new Float32Array(n).fill(Vrest), Iarr = new Float32Array(n);
  let v = Vrest, refrLeft = 0, t = 0, idx = 0;
  const fi = new Map();
  let key = null, sinceChange = 0, spikesSince = 0, lastSig = 0;
  const gauss = () =&gt; { let u = 0; while (u === 0) u = Math.random();
                        return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random()); };
  while (true) {
    const I0 = viewof lifI.value, sig = viewof lifNoise.value,
          tau = viewof lifTau.value, thr = viewof lifThr.value;
    if (!viewof lifPause.value) {
      const k = `${I0}|${sig &gt; 0}`;
      if (sig &gt; 0 && sig !== lastSig) { for (const [kk, p] of fi) if (p.noisy) fi.delete(kk); }
      if (sig &gt; 0) lastSig = sig;
      if (k !== key) { key = k; sinceChange = 0; spikesSince = 0; }
      const stepsPerFrame = viewof lifSpeed.value;
      for (let s = 0; s &lt; stepsPerFrame; s++) {
        idx = (idx + 1) % n;
        const I = I0 + sig * gauss() / Math.sqrt(dt);
        if (refrLeft &gt; 0) { refrLeft -= dt; v = Vreset; }
        else {
          v += dt / tau * ((Vrest - v) + R * I);
          if (v &gt;= thr) { v = 20; spikesSince++; refrLeft = refr; }
        }
        V[idx] = v; Iarr[idx] = I;
        if (v === 20) v = Vreset;
        t += dt; sinceChange += dt;
      }
      if (sinceChange &gt;= 500) fi.set(key, {I: I0, noisy: sig &gt; 0, rate: 1000 * spikesSince / sinceChange});
    }
    yield {V, Iarr, idx, t, win, fi, thr, tau, sig, I0, R, Vrest, refr,
           rate: sinceChange &gt; 0 ? 1000 * spikesSince / sinceChange : 0};
  }
}
