ft = {
  const T = ftT, dx = ftDx, N = Math.max(4, Math.floor(T / dx)), x0 = -T / 2;
  const sig = x =&gt; ftA1 * Math.sin(2 * Math.PI * ftF1 * x) + ftA2 * Math.sin(2 * Math.PI * ftF2 * x);
  const xs = Array.from({length: N}, (_, n) =&gt; x0 + n * dx), ys = xs.map(sig);
  const M = Math.floor(N / 2), re = new Float64Array(M + 1), im = new Float64Array(M + 1);
  for (let m = 0; m &lt;= M; m++) for (let n = 0; n &lt; N; n++) { const a = -2 * Math.PI * m * n / N; re[m] += ys[n] * Math.cos(a); im[m] += ys[n] * Math.sin(a); }
  const amp = Array.from({length: M + 1}, (_, m) =&gt; ({m, f: m / T, A: (m === 0 ? 1 : 2) * Math.hypot(re[m], im[m]) / N, ph: Math.atan2(im[m], re[m])}));
  const kept = amp.slice(1).sort((a, b) =&gt; b.A - a.A).slice(0, ftK);
  const rec = x =&gt; amp[0].A * Math.cos(amp[0].ph) + kept.reduce((s, c) =&gt; s + c.A * Math.cos(2 * Math.PI * c.f * (x - x0) + c.ph), 0);
  const fine = Array.from({length: 600}, (_, i) =&gt; x0 + T * i / 599);
  const fNy = 1 / (2 * dx);
  const alias = f =&gt; { const fs = 2 * fNy; let g = Math.abs(f - Math.round(f / fs) * fs); return g; };
  return {T, dx, N, x0, xs, ys, fine, sig, rec, amp, kept, fNy, alias};
}
