// Jacobi eigenvalue algorithm for a symmetric matrix; returns eigenvalues sorted descending with eigenvectors as rows
emEigh = A0 =&gt; {
  const n = A0.length, A = A0.map(row =&gt; Float64Array.from(row));
  const V = Array.from({length: n}, (_, i) =&gt; { const r = new Float64Array(n); r[i] = 1; return r; });
  for (let sweep = 0; sweep &lt; 60; sweep++) {
    let off = 0; for (let i = 0; i &lt; n; i++) for (let j = i + 1; j &lt; n; j++) off += A[i][j] * A[i][j];
    if (off &lt; 1e-20) break;
    for (let p = 0; p &lt; n; p++) for (let q = p + 1; q &lt; n; q++) {
      if (Math.abs(A[p][q]) &lt; 1e-14) continue;
      const theta = (A[q][q] - A[p][p]) / (2 * A[p][q]);
      const t = Math.sign(theta || 1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
      const c = 1 / Math.sqrt(t * t + 1), s = t * c;
