rnN = 256
rnKernel = {
  const N = rnN, sE = rnSigE, sI = rnSigI;
  const g = (d, s) =&gt; Math.exp(-0.5 * d * d / (s * s)) / s;
  const k = new Float64Array(N);
  for (let d = 0; d &lt; N; d++) { const dd = Math.min(d, N - d); k[d] = g(dd, sE) - g(dd, sI); }
  const ev = new Float64Array(N / 2 + 1);
  for (let m = 0; m &lt;= N / 2; m++) { let s = 0; for (let d = 0; d &lt; N; d++) s += k[d] * Math.cos(2 * Math.PI * m * d / N); ev[m] = s; }
  let lmax = -Infinity, mmax = 0; for (let m = 0; m &lt;= N / 2; m++) if (ev[m] &gt; lmax) { lmax = ev[m]; mmax = m; }
  const scale = rnGain / lmax;
  return {N, k: k.map(x =&gt; x * scale), ev: ev.map(x =&gt; x * scale), mmax};
}
rnState = {
  rnReset;
  const N = rnN, dt = 0.1, tau = 1;
  const h = Float64Array.from({length: N}, () =&gt; 0.5 + 0.5 * Math.random());
  let r = new Float64Array(N).fill(0.5), t = 0;
  while (true) {
    if (!viewof rnPause.value) {
      const {k} = rnKernel; const noise = viewof rnNoise.value, f = rnFuns[viewof rnNL.value], cap = 1e3;
      for (let step = 0; step &lt; 5; step++) {
        const rn = new Float64Array(N);
        for (let i = 0; i &lt; N; i++) {
          let s = 0;
          for (let j = 0; j &lt; N; j++) { const d = (i - j + N) % N; s += k[d] * r[j]; }
          const v = r[i] + dt / tau * (-r[i] + f(s + h[i] + noise * (Math.random() - 0.5) * 2));
          rn[i] = Math.max(-cap, Math.min(cap, v));
        }
        r = rn; t += dt;
      }
    }
    yield {r, t};
  }
}
